  }));
  const tenses=tenseNotebookEntries(data.value,currentDate.value).filter(e=>matches(e.w)&&(tab==='all'?true:tab==='imported'?!!data.value.importedWords?.[packageKey(e.p)+':'+e.baseWordId]:tab==='favorites'?e.favorite:tab==='errors'?e.errorActive:e.notebook===tab));
