async function load(){fatal.value='';try{const saved=await repo.load();const next=saved||initialState([]);next.settings.reviewMode||='both';next.settings.articleMode||='choice';next.settings.reminderTime||='08:00';next.settings.shuffleLearning??=false;next.settings.errorAutoRemove??=true;next.settings.reviewReminders??=true;next.settings.errorReminders??=true;next.settings.reviewErrorRetry??=true;next.settings.notifications=next.settings.reviewReminders;const cleaned=removeDemoLessons(next);applyCourseEntrySplits(next);const assets=await prepareBundledContent(next);try{await prepareExampleTranslations(next);}catch(e){notice(e.message);}applyMeaningCorrections(next);applyTextbookContent(next);applyExampleAudioCorrections(next);await loadAllLexicon();ensureConjugationCards(next);ensureImportedLessons(next);const conjugationAssets=await prepareConjugationAudio(next,repo);migrateSessions(next);syncPracticeBadges(next);recordLessonCompletions(next);await repo.save(next,[...(assets||[]),...conjugationAssets]);data.value=next;const chosen=next.homeSelection?next.homeSelection.lessonKey:next.lastPractice?.lessonKey;const course=[...next.library,...importedLessons(next)].find(p=>packageKey(p)===chosen&&p.book.id!=='personal');selectedKey.value=course?packageKey(course):'';selectedBookId.value=course?.book.id||next.homeSelection?.bookId||'';selectedSessionKey.value=course?sessionKey(course,'learn'):'';ready.value=true;await syncNativeReview(next);notificationPermission.value=getNotificationPermission();checkReviewReminder();}catch(e){fatal.value=e.message;}}
const paintFeedback=()=>new Promise(resolve=>{if(document.hidden){resolve();return;}requestAnimationFrame(()=>setTimeout(resolve,0));});
async function commit(action,assets=[],progressOnly=false){
 if(busy.value)return false;busy.value=true;
 try{
  if(progressOnly)await paintFeedback();
  const next=clone(toRaw(data.value));await action(next);
  if(!progressOnly){removeDemoLessons(next);applyCourseEntrySplits(next);applyMeaningCorrections(next);applyTextbookContent(next);applyExampleAudioCorrections(next);const added=ensureConjugationCards(next);if(added)assets=[...assets,...await prepareConjugationAudio(next,repo)];migrateSessions(next);}
  ensureImportedLessons(next);syncPracticeBadges(next);recordLessonCompletions(next);
  await repo.save(next,assets,{isolated:progressOnly});data.value=next;
  // Saving progress must not wait for the operating system's reminder service.
  const reminder=syncNativeReview(next);if(progressOnly)Promise.resolve(reminder).catch(()=>{});else await reminder;
  return true;
 }catch(e){notice(e.message||'操作失败 / Opération impossible.');return false;}finally{busy.value=false;}
}
