async function startImportedPractice(p=null,resume=false){
 if(!['practice','recite'].includes(view.value))importedOrigin.value=view.value==='books'?'books':view.value==='notebook'?'notebook':'lessons';
 const course=p?.importedLesson?p:currentImportedCourse.value||importedCourses.value.find(p=>packageKey(p)===selectedKey.value)||importedCourses.value.find(p=>lessonStats(data.value,p).practice)||importedCourses.value[0];
 if(!course){selectedBookId.value='imported';navigate('lessons');return;}
 const key=packageKey(course),active=activeImportedSession(data.value,key);
 selectedBookId.value='imported';selectedKey.value=key;
 if(resume&&active){if(!await commit(d=>rememberHomeSelection(d,'imported',key)))return;practiceReturnView.value=importedOrigin.value;selectedSessionKey.value=active.key;importedReciting.value=false;view.value='practice';return;}
 const entries=course.words.filter(w=>!w.conjugation);
 if(!entries.length){if(pendingConjugations(data.value,course).length){await openConjugationPractice(course);return;}notice('本课已学完 / Leçon terminée.');navigate('lessons');return;}
 if(await commit(d=>{d.importedRecitationIds=entries.map(w=>w.id);d.importedRecitationLesson=key;rememberHomeSelection(d,'imported',key);})){importedReciting.value=true;stopPlaying();view.value='recite';}
}
async function startImportedExercises(){
 const course=importedCourses.value.find(p=>packageKey(p)===data.value.importedRecitationLesson);if(!course)return;
 if(activeImportedSession(data.value,packageKey(course))){await startImportedPractice(course,true);return;}
 const chosen=new Set(data.value.importedRecitationIds||[]);
 let words=course.words.filter(w=>chosen.has(w.id)&&isVocabularyWord(w)&&getProgress(data.value,course,w).notebook==='practice');
 if(!words.length)words=course.words.filter(isVocabularyWord);
 if(!words.length){if(pendingConjugations(data.value,course).length)await openConjugationPractice(course);return;}
 if(data.value.settings.shuffleLearning)for(let i=words.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[words[i],words[j]]=[words[j],words[i]];}
 const ids=words.map(w=>w.id),order=new Map(ids.map((id,i)=>[id,i])),pool=reviewPackage(data.value);
 pool.words.sort((a,b)=>(order.get(a.id)??Infinity)-(order.get(b.id)??Infinity));
 await begin('direct',ids,pool,true,packageKey(course));practiceReturnView.value=importedOrigin.value;importedReciting.value=false;
}

async function removePracticeImported(w){const e=wordContext(data.value,currentPackage.value,w);if(await commit(d=>removeImportedEntry(d,e.p,e.w)))notice('已移出导入本 / Mot retiré.');}
function requestRemoveImported(entry=reviewDetail.value){if(!entry)return;confirmation.value={zh:'移出导入本？',fr:'Retirer des mots importés ?',detail:'保留全部本中的词条和学习记录。 / Le mot et sa progression sont conservés.',run:async()=>{if(await commit(d=>removeImportedEntry(d,entry.p,entry.w)))reviewDetail.value=null;}};}
function openImport(){importPreview.value=null;importOpen.value=true;}
async function downloadAudioNames(){
  const p=importPreview.value?.pkg;if(!p)return;
  const entries=p.words.flatMap(w=>{
    const grouped=new Map();for(const f of w.forms){const file=f.audio?.split('/').at(-1)||w.sourceAudio||numberedAudioName(w,f)||simpleAudioName(w,f);if(!grouped.has(file))grouped.set(file,[]);grouped.get(file).push(displayForm(w,f));}
    return [...grouped].map(([file,forms])=>[w.audioNumber||'',forms.join(' / '),file]);
  });
  const rows=[['音频编号','法语词条','录音文件'],...entries];
  const escape=value=>{const raw=String(value);return '"'+(/^[=+@-]/.test(raw)?"'"+raw:raw).replaceAll('"','""')+'"';};
  const csv='\uFEFF'+rows.map(row=>row.map(escape).join(',')).join('\r\n');try{await download(`${p.lesson.id}_录音命名清单.csv`,new TextEncoder().encode(csv),'text/csv');}catch(e){if(e.name!=='AbortError')notice(e.message);}
}
async function selectImport(){if(busy.value)return;try{const file=await chooseFile('.zip,.xlsx,.json',true);if(!file?.length)return;busy.value=true;const preview=await parseImport(file,{...importMeta,reservedIds:[...(data.value.reservedWordIds||[]),...Object.keys(data.value.progress).map(k=>k.split(':')[2]),...Object.keys(data.value.favorites).map(k=>k.split(':')[2]),...Object.values(data.value.errors).map(e=>e.wordId)]},data.value.library);const old=data.value.library.find(p=>packageKey(p)===packageKey(preview.pkg));if(old&&!old.demo&&preview.pkg.lesson.version<=old.lesson.version)throw new Error('请选择更高版本的课次包 / Une version plus récente est requise.');importPreview.value=preview;}catch(e){notice(`导入检查 / Vérification : ${e.message}`);}finally{busy.value=false;}}
async function applyImport(){const preview=importPreview.value;if(!preview)return;if(await commit(d=>{const pkg=clone(preview.pkg);for(const w of pkg.words)if(isVerb(w))w.conjugationPlan=clone(importConjugationPlan.value);installLesson(d,pkg);},preview.assets)){importOpen.value=false;importPreview.value=null;openRecitation(preview.pkg);notice('课次已导入 / Leçon importée.');}}
async function backup(){if(busy.value)return;busy.value=true;try{await download(`francais-backup-${day()}.zip`,await exportBackup(clone(data.value),repo),'application/zip');notice('词汇备份已导出 / Vocabulaire sauvegardé.');}catch(e){notice(e.message);}finally{busy.value=false;}}
async function restore(){try{const file=await chooseFile('.zip');if(!file)return;busy.value=true;const restored=await readBackup(file);busy.value=false;confirmation.value={zh:'用备份替换当前学习记录？',fr:'Restaurer cette sauvegarde ?',detail:'会替换本机词库、设置及进度，建议先导出当前备份。 / Le contenu local sera remplacé.',run:async()=>{if(await commit(d=>{for(const key of Object.keys(d))delete d[key];Object.assign(d,restored.data);},restored.assets)){navigate('books');notice('备份已恢复 / Sauvegarde restaurée.');}}};}catch(e){notice(e.message);}finally{busy.value=false;}}
watch([view,selectedKey],()=>{stopAudio();playing.value='';if(typeof window!=='undefined')window.scrollTo({top:0,behavior:'instant'});});
let reminderTimer,reviewNotification,reminderChecking=false;
async function startNextLesson(){if(nextLesson.value)await openRecitation(nextLesson.value);else{if(currentSession.value?.importedPractice)selectedBookId.value='imported';navigate('lessons');}}
async function startFavorites(){if(!data.value.library.some(p=>p.words.some(w=>isVocabularyWord(w)&&data.value.favorites[wordKey(p,w)]))&&pendingConjugations(data.value,null,'favorites').length){await openConjugationPractice(null,'favorites');return;}if(!favoriteWordCount.value&&!hasFavoritesInProgress.value)return;if(await commit(d=>startFavoritePractice(d))){practiceReturnView.value='notebook';selectedSessionKey.value=MIXED_FAVORITES_KEY;view.value='practice';}}
async function startErrors(){if(!data.value.library.some(p=>p.words.some(w=>isVocabularyWord(w)&&errorPracticeEligible(data.value,p,w)))&&pendingConjugations(data.value,null,'errors').length){await openConjugationPractice(null,'errors');return;}if(!errorWordCount.value&&!hasErrorsInProgress.value)return;if(await commit(d=>{startErrorPractice(d);acknowledgePractice(d,'errors');})){practiceReturnView.value='notebook';selectedSessionKey.value=MIXED_ERRORS_KEY;view.value='practice';}}
function reviewCountdown(entry,fr=false){const n=entry.tenseEntry?entry.daysLeft:reviewDaysLeft(data.value,entry.p,entry.w,currentDate.value);return n===null?'—':n===0?(fr?'À réviser':'今天复习'):(fr?'Dans '+n+' j':'剩余 '+n+' 天复习');}
async function setReminderTime(e){const value=e.detail?.value;if(/^(?:[01]\d|2[0-3]):[0-5]\d$/.test(value))await setSetting('reminderTime',value);}
async function toggleNotifications(enabled=!data.value.settings.reviewReminders){
 if(!enabled){await commit(d=>{d.settings.reviewReminders=false;d.settings.notifications=false;});return;}
 await commit(d=>{d.settings.reviewReminders=true;d.settings.notifications=true;});
 try{notificationPermission.value=await allowNotifications();if(notificationPermission.value==='granted'){syncNativeReview(data.value);if(exactAlarmPermission()==='denied')openExactAlarmSettings();checkReviewReminder();}else notice('请允许应用通知 / Autorisez les notifications.');}catch(e){notice(e.message);}
}

async function laterReview(){if(await commit(d=>snoozeReminder(d))){reviewReminderOpen.value=false;reviewNotification?.close();}}
async function reviewNow(){
  reviewReminderOpen.value=false;if(popupReminderCounts.value.review)await startTodayReview();else if(popupReminderCounts.value.errors){notebookTab.value='errors';await startErrors();}
}
async function checkReviewReminder(){
  clockNow.value=Date.now();
  if(!ready.value||busy.value||reminderChecking||(!activeReminderCounts.value.review&&!activeReminderCounts.value.errors))return;
  reminderChecking=true;
  try{
    if(activeMode.value==='vocabulary'&&!settingsOpen.value&&!modeDrawerOpen.value&&document.visibilityState==='visible'&&shouldRemind(data.value)&&view.value!=='practice'&&!help.value&&!shareOpen.value&&!importOpen.value&&!confirmation.value&&!moveDialog.value&&!reviewDetail.value){const counts=popupCounts(data.value);if(await commit(d=>markReminderShown(d))){popupReminderCounts.value=counts;reviewReminderOpen.value=true;}}
    if(data.value.settings.notifications&&shouldNotifyReview(data.value)){
      try{const counts=notificationCounts(data.value);reviewNotification=notifyReview(counts,()=>{notebookTab.value=counts.review?'review':'errors';navigate('notebook');});if(reviewNotification)await commit(d=>markNotificationSent(d,counts));}catch{notice('通知不可用 / Notifications indisponibles.');}
    }
  }finally{reminderChecking=false;}
}
function onVisibility(){if(document.visibilityState==='visible'){notificationPermission.value=getNotificationPermission();syncNativeReview(data.value);checkReviewReminder();}}
function nativeBack(e){if(practiceChoice.value){practiceChoice.value=null;e.preventDefault();return;}const close=document.querySelector('[data-conjugation-close]');if(close){close.click();e.preventDefault();return;}if(view.value==='conjugation'){closeConjugationPractice();e.preventDefault();return;}if(quickImportOpen.value){quickImportOpen.value=false;}else if(modeDrawerOpen.value){modeDrawerOpen.value=false;}else if(importOpen.value){importOpen.value=false;importPreview.value=null;}else if(shareOpen.value)shareOpen.value=false;else if(help.value)help.value=null;else if(confirmation.value)cancelConfirmation();else if(reviewDetail.value)reviewDetail.value=null;else if(moveDialog.value)returnToDefinition();else if(reviewReminderOpen.value)reviewReminderOpen.value=false;else if(settingsOpen.value)settingsOpen.value=false;else if(activeMode.value==='grammar'){if(!grammarMode.value?.handleBack())modeDrawerOpen.value=true;}else if(activeMode.value==='oral')modeDrawerOpen.value=true;else if(view.value==='practice')backFromPractice();else if(view.value==='lesson')view.value='lessons';else if(view.value==='recite'||view.value==='manuals'||view.value==='lessons')navigate('books');else if(view.value!=='books')navigate('books');else return;e.preventDefault();}
function onNativeReview(event){chooseMode('vocabulary');notebookTab.value=event.detail?.notebook==='errors'?'errors':'review';navigate('notebook');}
function onEscape(e){if(e.key==='Escape'){if(practiceChoice.value){practiceChoice.value=null;e.preventDefault();return;}const close=document.querySelector('[data-conjugation-close]');if(close){close.click();e.preventDefault();return;}if(view.value==='conjugation'){closeConjugationPractice();e.preventDefault();return;}if(quickImportOpen.value)quickImportOpen.value=false;else if(modeDrawerOpen.value)modeDrawerOpen.value=false;else if(importOpen.value){importOpen.value=false;importPreview.value=null;}else if(shareOpen.value)shareOpen.value=false;else if(help.value)help.value=null;else if(confirmation.value)cancelConfirmation();else if(moveDialog.value)returnToDefinition();else if(reviewDetail.value)reviewDetail.value=null;else if(settingsOpen.value)settingsOpen.value=false;else if(activeMode.value==='grammar'){if(!grammarMode.value?.handleBack())modeDrawerOpen.value=true;}else if(activeMode.value==='oral')modeDrawerOpen.value=true;else if(view.value==='practice')backFromPractice();}}
watch(activeReminderCounts,counts=>{if(!counts.review&&!counts.errors)reviewReminderOpen.value=false;});
let stopAccessibility;onMounted(()=>{stopAccessibility=accessibleButtons();load();reminderTimer=setInterval(checkReviewReminder,30000);document.addEventListener('visibilitychange',onVisibility);document.addEventListener('keydown',onEscape);window.addEventListener('qihang-back',nativeBack);window.addEventListener('qihang-review-open',onNativeReview);window.addEventListener('qihang-resume',onVisibility);});
onUnmounted(()=>{stopAccessibility?.();clearTimeout(toastTimer);clearInterval(reminderTimer);reviewNotification?.close();document.removeEventListener('visibilitychange',onVisibility);document.removeEventListener('keydown',onEscape);window.removeEventListener('qihang-back',nativeBack);window.removeEventListener('qihang-review-open',onNativeReview);window.removeEventListener('qihang-resume',onVisibility);stopAudio();});
</script>
